    /// PV2-49 viewed as the `CWE` that v2.8.2 prints (v2.5.1, v2.6 print `IS`). On a message of another version this views whatever PV2-49 holds on the wire.
    public var notifyClergyCodeAsCWEAll: [CWE] {
        repetitions(49).map(CWE.init(field:))
    }

    /// PV2-50: Advance Directive Last Verified Date. HL7 data type `DT`.
    /// Defined in v2.6, v2.8.2. On a message of another version this returns whatever PV2-50 holds on the wire.
    public var advanceDirectiveLastVerifiedDate: String? {
        field(50)?.stringValue
    }
}
